#include <algorithm> // std::swap

// Reverse the characters of `s` in place.
// Complexity: O(n) time, O(1) extra space.
void reverse(std::string& s) {
    // Use two indices moving toward each other.
    // `i` starts at the beginning, `j` at the end.
    for (std::size_t i = 0, j = s.size(); i < j; ++i, --j) {
        // Swap the characters at positions i and j-1.
        // The loop condition ensures we never swap a character with itself.
        std::swap(s[i], s[j - 1]);
    }
}

